try:
    print('>>> f = pow')
    print('>>> x = set()')
    print('>>> y = 3')
    print('>>> f(x, y)')
    f = pow
    x = set()
    y = 3
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
